import{_ as s,C as r,o as l,c as n,j as t,a as e,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const P=JSON.parse('{"title":"密码输入","description":"","frontmatter":{},"headers":[],"relativePath":"components/password-input.md","filePath":"components/password-input.md","lastUpdated":1787185306000}'),p={name:"components/password-input.md"},h={id:"密码输入",tabindex:"-1"};function u(b,d,g,x,w,f){const i=r("Badge"),a=r("XhDemo");return l(),n("div",null,[t("h1",h,[d[0]||(d[0]=e("密码输入 ",-1)),o(i,{type:"info",text:"password-input"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#密码输入","aria-label":'Permalink to "密码输入 <Badge type="info" text="password-input" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一格密码框，带明暗切换钮，并在大写锁定开着时给出提示。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>登录、注册、改密码这类要遮住输入内容的字段。</li><li>输错了要能自己核对：切成明文看一眼，再切回去。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只要一格遮起来的输入、不需要明暗切换与大写锁定提示：用<a href="./text-field">文本输入</a>的 <code>type=&quot;password&quot;</code> 就够了，少一层结构。</li><li>收的是短验证码或一次性密码：用<a href="./pin-input">分格输入</a>。</li><li>要在同一页比较两次输入是否一致：那是表单校验的活儿，交给<a href="./form">表单</a>与<a href="./field">表单字段</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>明暗切换在 <code>visible</code> / <code>defaultVisible</code> 两态齐全，受控与非受控都走同一条路。</li><li>切换之后焦点留在切换钮上，框里的光标与选中范围原样放回。</li><li>大写锁定提示由按键事件驱动，焦点离开输入框即熄灭。</li><li><code>autoComplete</code> 缺省 <code>current-password</code>，注册表单要显式改成 <code>new-password</code>。</li><li>形态 · 语气 · 尺寸三轴与<a href="./text-field">文本输入</a>同源，并排放不会差一档。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>root 持有状态，control 是那个视觉盒；不传 value 与 visible 即为非受控，明暗由组件自己管，钮里的图标跟着明暗换</p>',10)),o(a,{src:"password-input/01-basic"}),d[4]||(d[4]=t("h3",{id:"受控",tabindex:"-1"},[e("受控 "),t("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[5]||(d[5]=t("p",null,"值与明暗都能受控：传了就由宿主说了算，组件只把意图报出来，写不写回由宿主定",-1)),o(a,{src:"password-input/02-controlled"}),d[6]||(d[6]=t("h3",{id:"大写锁定提示",tabindex:"-1"},[e("大写锁定提示 "),t("a",{class:"header-anchor",href:"#大写锁定提示","aria-label":'Permalink to "大写锁定提示"'},"​")],-1)),d[7]||(d[7]=t("p",null,"打开大写锁定再往框里敲一个字：提示显出来，读屏也会念一次；焦点离开输入框即熄灭",-1)),o(a,{src:"password-input/03-caps-lock"}),d[8]||(d[8]=t("h3",{id:"禁用与校验态",tabindex:"-1"},[e("禁用与校验态 "),t("a",{class:"header-anchor",href:"#禁用与校验态","aria-label":'Permalink to "禁用与校验态"'},"​")],-1)),d[9]||(d[9]=t("p",null,"disabled 连明暗一起停掉，read-only 只锁值、明暗照切，invalid 只标注不拦输入",-1)),o(a,{src:"password-input/04-states"}),d[10]||(d[10]=t("h3",{id:"形态",tabindex:"-1"},[e("形态 "),t("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),d[11]||(d[11]=t("p",null,"variant 决定底与描边怎么画：描边、淡色填底、无框；密码框没有实心档",-1)),o(a,{src:"password-input/05-variant"}),d[12]||(d[12]=t("h3",{id:"语气",tabindex:"-1"},[e("语气 "),t("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),d[13]||(d[13]=t("p",null,"tone 决定用哪族颜色，与 variant 正交；这里固定 subtle 形态，语气的底色差别不必聚焦就看得见",-1)),o(a,{src:"password-input/06-tone"}),d[14]||(d[14]=t("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[15]||(d[15]=t("p",null,"size 只改高度、内边距与字号，标签、切换钮与大写锁定提示一起跟着换档；不写就是缺省档",-1)),o(a,{src:"password-input/07-size"}),d[16]||(d[16]=t("h3",{id:"注册表单",tabindex:"-1"},[e("注册表单 "),t("a",{class:"header-anchor",href:"#注册表单","aria-label":'Permalink to "注册表单"'},"​")],-1)),d[17]||(d[17]=t("p",null,"name 才让它参与提交，auto-complete 写成 new-password 密码管理器才去存新密码而不是填旧的",-1)),o(a,{src:"password-input/08-register"}),d[18]||(d[18]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-password-input&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPasswordInputCapsLockIndicator</code> <code>XhPasswordInputControl</code> <code>XhPasswordInputInput</code> <code>XhPasswordInputLabel</code> <code>XhPasswordInputRoot</code> <code>XhPasswordInputVisibilityTrigger</code></td></tr><tr><td>组合式函数</td><td><code>usePasswordInput</code></td></tr><tr><td>状态机</td><td><code>passwordInputMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/password-input.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;password-input&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <code>control</code> · <strong><code>input</code></strong> · <strong><code>visibility-trigger</code></strong> · <code>caps-lock-indicator</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>受控值；给了就由宿主说了算，机器不自改。</td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td></td><td>非受控初值。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td></td><td>受控的明暗态；给了就由宿主说了算。</td></tr><tr><td><code>defaultVisible</code></td><td><code>boolean</code></td><td></td><td>非受控的初始明暗态，缺省隐藏。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了才参与提交。</td></tr><tr><td><code>placeholder</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>autoComplete</code></td><td><code>string</code></td><td></td><td>落到 input 上的 autocomplete，缺省 current-password。 密码管理器靠它决定这一格是填旧密码还是存新密码，注册表单要显式写 new-password。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;PasswordInputTranslations&gt;</code></td><td></td><td>读屏文案覆盖；没给的条目走组件内建英文。</td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline / subtle / ghost，决定颜色怎么用。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: PasswordInputValueChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onVisibilityChange</code></td><td><code>(details: PasswordInputVisibilityChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>PasswordInputValueChangeDetails</code></td><td>值变化；detail 为 <code>{ value: string }</code></td></tr><tr><td><code>visibility-change</code></td><td><code>PasswordInputVisibilityChangeDetails</code></td><td>明暗变化；detail 为 <code>{ visible: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPasswordInputRoot</code></td><td><code>default</code></td><td><code>PasswordInputRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>visibility-trigger</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>caps-lock-indicator</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>VISIBILITY.SET</code> · <code>VISIBILITY.TOGGLE</code> · <code>CAPS_LOCK.SET</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canEdit</code> · <code>canToggleVisibility</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>usePasswordInput</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>值为空串。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td>此刻是否明文显示。</td></tr><tr><td><code>capsLock</code></td><td><code>boolean</code></td><td>大写锁定是否开着；为真时提示部件才显出来。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>inputType</code></td><td><code>PasswordInputType</code></td><td>输入框此刻的 type，随 visible 走。</td></tr><tr><td><code>capsLockMessage</code></td><td><code>string</code></td><td>大写锁定播报区里此刻的文字：开着时是 <code>translations.capsLockOn</code>，关着时是空串。 适配器把它落成提示部件的文本内容，读屏念的就是这一段。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td>直接写值，只受 disabled / readOnly 约束。</td></tr><tr><td><code>setVisible</code></td><td><code>(next: boolean) =&gt; void</code></td><td>指定明暗态；整枚控件禁用时不生效。</td></tr><tr><td><code>toggleVisibility</code></td><td><code>() =&gt; void</code></td><td>翻转明暗态；整枚控件禁用时不生效。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td></td></tr><tr><td><code>getVisibilityTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCapsLockIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on visibility-trigger, 控件未禁用</td><td>切换明暗；切换钮是原生 button，这两个键由平台翻成 click。焦点留在按钮上，框里的光标与选中范围原样放回</td></tr><tr><td><code>CapsLock</code></td><td>focus in input</td><td>每次按键都重读一次大写锁定状态：开着就亮起提示，焦点离开输入框即熄灭</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>aria-describedby</code></td><td><code>capsLock</code> 部件的 id | undefined</td></tr><tr><td><code>input</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>visibility-trigger</code></td><td><code>aria-controls</code></td><td><code>password-input-input</code> 部件的 id</td></tr><tr><td><code>visibility-trigger</code></td><td><code>aria-label</code></td><td>label.visibilityTriggerHide | label.visibilityTriggerShow</td></tr><tr><td><code>caps-lock-indicator</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>caps-lock-indicator</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>caps-lock-indicator</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><ul><li>切换钮的名字随状态换：隐藏时叫「显示密码」，显示时叫「隐藏密码」，两句都走 <code>translations</code>。名字既然已经说清了此刻是明是暗，就不再叠 <code>aria-pressed</code>——两个通道各说各的会念成「隐藏密码 已按下」，听的人反而分不清。</li><li>切换钮的 <code>aria-controls</code> 指向输入框，读屏能顺着它跳到被切换的那一格。</li><li>大写锁定提示是 <code>role=&quot;status&quot;</code> 的活区域，节点恒在场、恒渲染，开与关只换区内文字。活区域播报的是内容变化，区域本身若被 <code>hidden</code> 或 <code>display: none</code> 撤下去，再出现时读屏当作插入了个新节点，多数不念——所以这一块不做按需挂载，也不靠收起与显出来触发播报。</li><li>提示区的文字就是 <code>translations.capsLockOn</code>，由组件写进节点，作者把这个节点留空即可；要配图标就往这个 part 上挂 <code>::before</code>。</li><li>焦点晚于提示出现的用户，靠输入框的 <code>aria-describedby</code> 也听得到同一句。</li><li>输入框恒带 <code>spellcheck=&quot;false&quot;</code> / <code>autocapitalize=&quot;off&quot;</code> / <code>autocorrect=&quot;off&quot;</code>：切成明文那一刻它就是普通文本框，拼写检查会把框里的内容发去远端服务，移动端还会给首字母自动大写并按词典纠错。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/password-input.css</code> 按部件选择：<code>[data-scope=&quot;password-input&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>visibility-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>visibility-trigger</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>caps-lock-indicator</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-password-input-control-bg</code> · <code>--xh-password-input-control-bg-disabled</code> · <code>--xh-password-input-control-bg-readonly</code> · <code>--xh-password-input-control-border</code> · <code>--xh-password-input-control-border-focus</code> · <code>--xh-password-input-control-border-hover</code> · <code>--xh-password-input-control-border-invalid</code> · <code>--xh-password-input-control-h</code> · <code>--xh-password-input-gap</code> · <code>--xh-password-input-hint-fg</code> · <code>--xh-password-input-hint-font-size</code> · <code>--xh-password-input-hint-gap</code> · <code>--xh-password-input-hint-px</code> · <code>--xh-password-input-icon-size</code> · <code>--xh-password-input-input-bg</code> · <code>--xh-password-input-input-bg-disabled</code> · <code>--xh-password-input-input-bg-readonly</code> · <code>--xh-password-input-input-border</code> · <code>--xh-password-input-input-border-focus</code> · <code>--xh-password-input-input-border-hover</code> · <code>--xh-password-input-input-border-invalid</code> · <code>--xh-password-input-input-fg</code> · <code>--xh-password-input-input-font-size</code> · <code>--xh-password-input-input-h</code> · <code>--xh-password-input-input-px</code> · <code>--xh-password-input-input-radius</code> · <code>--xh-password-input-label-fg</code> · <code>--xh-password-input-label-fg-disabled</code> · <code>--xh-password-input-label-font-size</code> · <code>--xh-password-input-label-font-weight</code> · <code>--xh-password-input-placeholder-fg</code> · <code>--xh-password-input-trigger-bg</code> · <code>--xh-password-input-trigger-bg-active</code> · <code>--xh-password-input-trigger-bg-hover</code> · <code>--xh-password-input-trigger-fg</code> · <code>--xh-password-input-trigger-fg-hover</code> · <code>--xh-password-input-trigger-font-size</code> · <code>--xh-password-input-trigger-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>拿标签、说明与错误文本。</li><li>切换钮里放<a href="./icon">图标</a>，随明暗换一只眼睛。钮上带 <code>data-state</code>（<code>visible</code> / <code>hidden</code>），作者用自己的 CSS 按它切两枚图标即可；也可以从 root 的默认插槽拿 <code>visible</code>（Vue）或听 <code>visibility-change</code>（Web Components）自己换。皮肤不替作者切图标——库里不知道那两枚图标长什么样。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>自己写角色节点时（Web Components 用法），三个角色必须用对标签：标题是原生 <code>&lt;label&gt;</code>、输入框是原生 <code>&lt;input&gt;</code>、切换钮是原生 <code>&lt;button&gt;</code>。标题的 <code>for</code> 恒写向输入框的 id，写成 <code>&lt;span&gt;</code> 就点不动；切换钮写成 <code>&lt;div&gt;</code> 就没有 Enter / Space 激活——两种都不报错，只是静默失效。</li><li>大写锁定提示这个节点也得由作者写出来（元素不生成结构），写成空壳即可，文字由组件填。Vue 侧这些由组件代劳，作者不会写错。</li><li>明文只在用户主动切开时出现，别默认 <code>defaultVisible</code>：屏幕背后有别人。</li><li>切换钮别在切开后消失或换位置：它承着焦点，一动键盘用户就丢了位置。</li><li>大写锁定提示只提示，不拦提交：它是键盘的物理状态，用户可能就是要打大写。</li><li>注册表单把 <code>autoComplete</code> 写成 <code>new-password</code>，否则密码管理器会把旧密码填进来。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它收「请再输一次」的确认格却不给自己的标签：读屏念出来的两格一模一样。</li><li>把明暗态存进接口或本地存储：下一次打开页面时密码是明着的。</li></ul>',49))])}const q=s(p,[["render",u]]);export{P as __pageData,q as default};
